package cli_test

import (
	"bytes"
	"os"
	"path/filepath"
	"testing"
)

func TestCLICommands(t *testing.T) {
	tests := []struct {
		name     string
		args     []string
		wantExit int
		wantOut  string
		wantErr  string
	}{
		// Init command
		{"init creates config", []string{"init"}, 0, "initialized", ""},
		{"init with path", []string{"init", "--config", "/tmp/cfg"}, 0, "initialized", ""},

		// Get command
		{"get existing key", []string{"get", "database.host"}, 0, "localhost", ""},
		{"get missing key", []string{"get", "nonexistent"}, 1, "", "key not found"},

		// Set command
		{"set valid", []string{"set", "port", "8080"}, 0, "", ""},
		{"set no value", []string{"set", "port"}, 2, "", "usage:"},

		// Delete command
		{"delete existing", []string{"delete", "cache"}, 0, "", ""},
		{"delete missing", []string{"delete", "ghost"}, 1, "", "not found"},

		// Validate command
		{"validate good config", []string{"validate"}, 0, "valid", ""},

		// List command
		{"list all", []string{"list"}, 0, "database", ""},
		{"list json format", []string{"list", "--format", "json"}, 0, "{", ""},

		// Flags
		{"quiet suppresses output", []string{"get", "key", "--quiet"}, 0, "", ""},
		{"verbose shows debug", []string{"get", "key", "--verbose"}, 0, "DEBUG", ""},

		// Edge cases
		{"no args shows help", []string{}, 2, "", "usage"},
		{"unknown command", []string{"explode"}, 2, "", "unknown command"},
		{"help flag", []string{"--help"}, 0, "usage", ""},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			stdout, stderr := &bytes.Buffer{}, &bytes.Buffer{}
			exit := runCLI(tt.args, stdout, stderr)

			if exit != tt.wantExit {
				t.Errorf("exit = %d, want %d", exit, tt.wantExit)
			}
			if tt.wantOut != "" && !bytes.Contains(stdout.Bytes(), []byte(tt.wantOut)) {
				t.Errorf("stdout missing %q", tt.wantOut)
			}
			if tt.wantErr != "" && !bytes.Contains(stderr.Bytes(), []byte(tt.wantErr)) {
				t.Errorf("stderr missing %q", tt.wantErr)
			}
		})
	}
}

func TestFileOperations(t *testing.T) {
	tests := []struct {
		name    string
		setup   func(string)
		args    []string
		verify  func(t *testing.T, dir string)
	}{
		{
			"init creates file",
			nil,
			[]string{"init"},
			func(t *testing.T, dir string) {
				if _, err := os.Stat(filepath.Join(dir, "config.yaml")); err != nil {
					t.Error("config file not created")
				}
			},
		},
		{
			"set persists value",
			func(d string) { os.WriteFile(filepath.Join(d, "config.yaml"), []byte("{}"), 0644) },
			[]string{"set", "key", "value"},
			func(t *testing.T, dir string) {
				data, _ := os.ReadFile(filepath.Join(dir, "config.yaml"))
				if !bytes.Contains(data, []byte("value")) {
					t.Error("value not persisted")
				}
			},
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			dir := t.TempDir()
			if tt.setup != nil {
				tt.setup(dir)
			}
			args := append([]string{"--config", dir}, tt.args...)
			runCLI(args, &bytes.Buffer{}, &bytes.Buffer{})
			tt.verify(t, dir)
		})
	}
}
